#!/usr/bin/env node
// Generates lib/src/schemas.ts — the library's schema bundle. schemas/
// stays the single source of truth; scripts/validate.mjs enforces
// freshness (a drifted bundle fails the coherence gate). Never edit the
// generated file: change schemas/ and re-run this script.
//
// Since Faden 3 (29.08.2026) the simulator no longer gets its own
// emission: simulator/rltp-schemas.mjs is a permanent shim onto the
// frozen library copy (simulator/lib/schemas.js) — one generator, ONE
// emission, and the frozen copy is freshness-checked byte-identically
// by scripts/build-simulator-lib.mjs --check in CI.
//
//   usage: node scripts/build-schemas-module.mjs           (write)
//          node scripts/build-schemas-module.mjs --check   (drift, exit 1)
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const files = readdirSync(join(ROOT, 'schemas')).filter((f) => f.endsWith('.json')).sort()
const entries = files.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(JSON.parse(readFileSync(join(ROOT, 'schemas', f), 'utf8')))},`)
const out = `// GENERATED by scripts/build-schemas-module.mjs — DO NOT EDIT.
// Source of truth: schemas/*.json. npm run validate enforces freshness (--check).
// DEEP-FROZEN: these objects gate what receivers accept — code in the
// same realm must not be able to weaken them in place (lib review 4, B-4).
const freeze = (o) => { if (o && typeof o === 'object') { for (const v of Object.values(o)) freeze(v); Object.freeze(o) } return o }
export const SCHEMAS = freeze({
${entries.join('\n')}
})
`
const tsOut = out
  .replace('const freeze = (o) =>', 'const freeze = (o: any): any =>')
  .replace('export const SCHEMAS = freeze({',
    'export const SCHEMAS: Readonly<Record<string, Readonly<Record<string, unknown>>>> = freeze({')
if (process.argv.includes('--check')) {
  const fresh = readFileSync(join(ROOT, 'lib/src/schemas.ts'), 'utf8') === tsOut
  console.log(fresh ? `lib/src/schemas.ts: fresh, ${files.length} schemas` : 'lib/src/schemas.ts: STALE — run node scripts/build-schemas-module.mjs')
  if (!fresh) process.exit(1)
} else {
  writeFileSync(join(ROOT, 'lib/src/schemas.ts'), tsOut)
  console.log(`lib/src/schemas.ts: ${files.length} schemas bundled`)
}
